  trapTitle: { en: (a, b) => `Why so high between ${a} and ${b}?`, nl: (a, b) => `Waarom zo hoog tussen ${a} en ${b}?`, fr: (a, b) => `Pourquoi si élevé entre ${a} et ${b} ?` },
  trapBody: {
    en: (a, b, red, ded) => `At the minimum wage (${a}) you pay no income tax. Two things make sure of it: up to ${red} of work income is not taxed, and there is a tax deduction for low earners. Both shrink as your pay goes up: the deduction is gone at ${ded} gross a year, the untaxed part at ${b}. So each extra euro here is taxed normally and also takes away part of that help. Above ${b} you're back to the normal rates.`,
    nl: (a, b, red, ded) => `Op het minimumloon (${a}) betaal je geen inkomstenbelasting. Twee dingen zorgen daarvoor: tot ${red} arbeidsinkomen wordt niet belast, en er is een belastingaftrek voor lage lonen. Beide krimpen als je loon stijgt: de aftrek is weg bij ${ded} bruto per jaar, het onbelaste deel bij ${b}. Elke extra euro hier wordt dus normaal belast en neemt ook een deel van die hulp weg. Boven ${b} gelden weer de gewone tarieven.`,
    fr: (a, b, red, ded) => `Au salaire minimum (${a}), vous ne payez pas d'impôt sur le revenu. Deux choses y veillent : jusqu'à ${red} de revenus du travail ne sont pas imposés, et il y a une déduction d'impôt pour les bas salaires. Les deux diminuent quand le salaire monte : la déduction disparaît à ${ded} brut par an, la part non imposée à ${b}. Chaque euro en plus est donc imposé normalement et fait aussi perdre une partie de cette aide. Au-delà de ${b}, on revient aux taux normaux.`,
  },
  topTitle: {
    en: (top, rate) => `Why the step at ${top}?`,
    nl: (top, rate) => `Waarom de sprong bij ${top}?`,
    fr: (top, rate) => `Pourquoi la marche à ${top} ?`,
  },
  topBody: {
    en: (top, rate, br, cap) => `From ${top}, your taxable income goes above ${br}. Both the national and the regional highest rates apply: ${rate} on each extra euro. Note the dip earlier, from ${cap}: social security stops at its pay limit, and only a small "solidarity" contribution is left.`,
    nl: (top, rate, br, cap) => `Vanaf ${top} komt je belastbaar inkomen boven ${br}. Dan gelden de hoogste tarieven van zowel de staat als de regio: ${rate} op elke extra euro. Let ook op de dip vanaf ${cap}: de sociale bijdragen stoppen aan hun loongrens, en er blijft alleen een kleine "solidariteitsbijdrage".`,
    fr: (top, rate, br, cap) => `À partir de ${top}, votre revenu imposable dépasse ${br}. Les taux les plus hauts de l'État et de la région s'appliquent : ${rate} sur chaque euro en plus. Notez le creux plus tôt, dès ${cap} : les cotisations s'arrêtent à leur limite de salaire, et il ne reste qu'une petite cotisation de « solidarité ».`,
  },

